/**
 * Represents a unique key for ensuring idempotency of an operation.
 * This is typically generated by the client or event producer.
 */
export type IdempotencyKey = string;

/**
 * Interface for a PaymentProcessedEvent.
 * This event signifies that a payment has been successfully processed.
 */
export interface PaymentProcessedEvent {
  eventId: string; // Unique ID for this specific event instance
  idempotencyKey: IdempotencyKey; // Key to ensure payment processing is idempotent
  orderId: string;
  userId: string;
  amount: number;
  currency: string;
  transactionId: string; // ID from the payment gateway
  processedAt: string;
}

/**
 * Interface for a PaymentFailedEvent.
 */
export interface PaymentFailedEvent {
  eventId: string;
  idempotencyKey: IdempotencyKey;
  orderId: string;
  userId: string;
  amount: number;
  currency: string;
  reason: string;
  failedAt: string;
}

// Union type for all payment-related events
export type PaymentEvent = PaymentProcessedEvent | PaymentFailedEvent;
